DROP POLICY IF EXISTS "Admins can manage all fine payments" ON public.employee_fine_payments; CREATE POLICY "Admins can manage all fine payments" ON public.employee_fine_payments AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM users u
  WHERE ((u.id = uid()) AND (u.user_type = 'global'::user_type_enum)))));
DROP POLICY IF EXISTS "Admins can view all device sessions" ON public.user_device_sessions; CREATE POLICY "Admins can view all device sessions" ON public.user_device_sessions AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = uid()) AND (users.user_type = 'global'::user_type_enum)))));
DROP POLICY IF EXISTS "Allow admin users to delete parent categories" ON public.expense_parent_categories; CREATE POLICY "Allow admin users to delete parent categories" ON public.expense_parent_categories AS PERMISSIVE FOR DELETE TO authenticated USING (true);
DROP POLICY IF EXISTS "Allow admin users to delete sub categories" ON public.expense_sub_categories; CREATE POLICY "Allow admin users to delete sub categories" ON public.expense_sub_categories AS PERMISSIVE FOR DELETE TO authenticated USING (true);
DROP POLICY IF EXISTS "Allow admin users to insert parent categories" ON public.expense_parent_categories; CREATE POLICY "Allow admin users to insert parent categories" ON public.expense_parent_categories AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (true);
DROP POLICY IF EXISTS "Allow admin users to insert sub categories" ON public.expense_sub_categories; CREATE POLICY "Allow admin users to insert sub categories" ON public.expense_sub_categories AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (true);
DROP POLICY IF EXISTS "Allow admin users to update parent categories" ON public.expense_parent_categories; CREATE POLICY "Allow admin users to update parent categories" ON public.expense_parent_categories AS PERMISSIVE FOR UPDATE TO authenticated USING (true);
DROP POLICY IF EXISTS "Allow admin users to update sub categories" ON public.expense_sub_categories; CREATE POLICY "Allow admin users to update sub categories" ON public.expense_sub_categories AS PERMISSIVE FOR UPDATE TO authenticated USING (true);
